  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '25b24d3a-9d47-44af-b460-680508e644f3', 'Enfrentando los juegos de integración con soltura y actitud positiva.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '2f8359db-221e-4a64-b2df-2b3e7b74a2db', 'Manifestando empatía y calidez en los encuentros de patrulla.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '3621f4ae-1316-4b3e-8682-3e3c9ad381a7', 'Promoviendo relaciones afectivas sanas y respetuosas en la unidad.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb', 'Facilitando un clima de confianza fraterna donde todos se sientan valorados.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4d66ed86-48ec-4801-bd0a-e5c8d023c8cd', 'Viviendo la dinámica con sentido del humor y alegría compartida.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '5cbe35dc-d15b-4070-9a36-5b0e652c7946', 'Incluyendo activamente a los lobatos más tímidos en el círculo.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '6e25f6ed-277c-41b4-9d0f-322b0a2d4c94', 'Brindando abrazos respetuosos y cariñosos a mis compañeros al detenerse la música.') ON CONFLICT DO NOTHING;
