  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '944660c8-0093-4181-ba2c-5f95cc74ba47', 'Velando por el bienestar y la comodidad emocional de las compañeras.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '9a38e454-f93a-40a5-9f68-e500ba7e0655', 'Fomentando el optimismo y la buena energía al dinamizar el encuentro.') ON CONFLICT DO NOTHING;
